package com.maxrave.kotlinytmusicscraper.pages

import com.maxrave.kotlinytmusicscraper.models.AlbumItem
import com.maxrave.kotlinytmusicscraper.models.Artist
import com.maxrave.kotlinytmusicscraper.models.ArtistItem
import com.maxrave.kotlinytmusicscraper.models.PlaylistItem
import com.maxrave.kotlinytmusicscraper.models.SongItem
import com.maxrave.kotlinytmusicscraper.models.response.SearchResponse
import kotlinx.serialization.json.Json
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull

class SearchAllPageTest {
    private val json =
        Json {
            ignoreUnknownKeys = true
            explicitNulls = false
        }

    private val drake = Artist("Drake", "UCU6cE7pdJPc6DU2jSrKEsdQ")

    @Test
    fun topResultAndRows() {
        val page = json.decodeFromString<SearchResponse>(FIXTURE).toSearchAllPage()

        val top = page.top as ArtistItem
        assertEquals("Drake", top.title)
        assertEquals(drake.id, top.id)
        assertNotNull(top.radioEndpoint)
        assertEquals("Artist • 130M monthly audience", page.topSubtitle)

        // The card's rows say "Song • 4:01": the length is the duration, the card's artist the artist.
        assertEquals(listOf("4pm in Calabasas", "Hoe Phase"), page.topSongs.map { it.title })
        assertEquals(listOf(listOf(drake), listOf(drake)), page.topSongs.map { it.artists })
        assertEquals(241, page.topSongs[0].duration)

        assertEquals(listOf("ICEMAN"), page.items.filterIsInstance<AlbumItem>().map { it.title })
        assertEquals(listOf("Nick Drake"), page.items.filterIsInstance<ArtistItem>().map { it.title })
        assertEquals(listOf("Drake Late Night Drive Songs"), page.items.filterIsInstance<PlaylistItem>().map { it.title })
        val songs = page.items.filterIsInstance<SongItem>().associateBy { it.title }
        assertEquals(listOf(drake), songs.getValue("The Ride").artists)
        assertEquals("MUSIC_VIDEO_TYPE_OMV", songs.getValue("I’m Spent").musicVideoType)
        // Profiles and podcast shows are no kind the page shows, so they don't parse.
        assertEquals(6, page.items.size)
    }
}

